--
-- Volcado de datos para la tabla `proyecto`
--

INSERT INTO `proyecto` (`ID_PROYECTO`, `CLAVE`, `PROYECTO`, `OBJETIVO`, `PARTICIPANTES`) VALUES
(1, 'CONACYT 214582', '\"Disminución en el consumo de agua para el proceso de ultrapasteurización, mediante el diseño, construcción y puesta en marcha de sistemas de recuperación de agua de enfriamiento, en homogeneizadores - Empresa Complejo Lala UHT Grupo Lala – CONACYT 214582\"', '\"Diseñar y construir sistema de recuperación de agua en envasadoras, para disminuir el consumo de agua en planta y contar con procesos sustentables. Automatizar el proceso de bombeo de agua con peróxido de envasadoras hacia una planta tratadora de agua. Automatización de dicha planta.\"', 'Juan Manuel Martínez Burrola / Armando José Cordero Escamilla / Víctor Edi Manqueros Avilés / Diego Alberto Román Landeros / Efraín Vaquera González / Noé Alvarado Tovar'),
(2, 'CONACYT 209808', '\"Diseño e Implementación de Sistema de Monitoreo, Automatización y Control en Tiempo Real de Parámetros Fisicoquímicos y Microbiológicos de Leche Concentrada para Elaboración de Derivados Lácteos y Postres  - Empresa Transportadora de Alimentos S.A de C.V. Grupo Lala – CONACYT 209808\"', '\"Diseñar y construir el sistema de monitoreo de ciertos parámetros de leche concentrada. Integrar las variables de PH y Conductividad a un sistema de monitoreo continuo de adquisición de datos, para un mayor control de la calidad de la leche en los silos de almacenamiento.  Así como el rastreo de las pipas transportadoras de leche en territorio nacional. Añadir al sistema de medición de los silos la medición de pH y CE del Silo de leche concentrada, búsqueda de instrumentos adecuados, instalación de los mismos, calibración, puesta en marcha y agregar las variables de medición al sistema SCADA.\"', 'Luis Amado González Vargas / Víctor Edi Manqueros Avilés / Juan Manuel Martínez Burrola'),
(3, 'CONACYT 213198', '\"Plataforma de Seguimiento ORBE KULTIVA con apoyo en GPS Y RFID - Empresa Orbe Kultiva, S.A. – CONACYT 213198\"', '\"Diseñar, desarrollar un sistema de monitoreo y control para la supervisión total, permanente de todos los procesos para la distribución de productos agrícolas, mediante un tablero virtual, interactivo y multipunto en tiempo real. Utilizar la tecnología RFID para administrar la información de los trabajadores y las actividades que han sido asignados en la planta.\"', 'Karla Verónica Rodríguez Lozano /  Nancy Gabriela Marín Castañeda'),
(4, 'CONACYT 221224', 'Producción de alimento para ganado peletizado a partir de moringa oleífera. Empresa Moringa del desierto SPR de RL de CV - CONACYT 221224', '\"Elaboración de prototipo para generar alimento mediante peletizado, consistente en un proceso de aglomeración de partículas de restos orgánicos que posteriormente son transformadas en porciones digeribles para los animales mediante un proceso mecánico\"', 'Arturo Serrano Hernández'),
(5, 'CONACYT 232498	', '\"Reingeniería de los sistemas clave de turbinas de gas generadoras de energía 337MW para exportación – Empresa Equinox - Equipos Inoxidables del Norte, S.A. de C.V. - CONACYT 232498\"', '\"Reingeniería e innovación en el diseño de una planta compacta de generación de energía eléctrica a través del análisis y mejoramiento de todos sus subsistemas y el desempeño final del equipo, de manera tal que represente una opción atractiva para los usuarios finales en todo el mundo.\"', 'Noé Alvarado Tovar / Francisco Huerta Valenzuela / Arturo Serrano Hernández  / Ernesto II Castro Juárez / Diego Alberto Román Landeros / Efraín Vaquera González'),
(6, 'CONACYT 232056', '\"Diseño e implementación de un nuevo proceso para la fabricación de camastro solar SolarCOT de polietileno de alta densidad por medio de corte con chorro de agua y su automatización – Empresa MEDIZONE, S.A. de C.V. -CONACYT 232056\"	\r\n', '\"Desarrollar un nuevo proceso que contenga el uso de tecnología de corte mediante el Diseño e implementación de una máquina de corte de polietileno de alta densidad para ser empleada en la fabricación de un camastro solar (SolarCOT es un camastro para ser empleado en zona de playa, incluye panel solar, cargador de dispositivos, enfriador de bebidas bocinas y caja de seguridad) por medio de tecnología CNC de 5 ejes para corte que propicie la reducción de residuos, aumente la productividad y la seguridad a los operarios usuarios. Además de fomentar la asimilación del conocimiento y el uso de la tecnología para el desarrollo y fabricación de este tipo de equipos a nivel nacional proporcionando la oportunidad de ser generadores de tecnología al no depender de la importación de los equipos o sus componentes.\"', 'Noé Alvarado Tovar / Francisco Huerta Valenzuela / Arturo Serrano Hernández  / Víctor Edi Manqueros Avilés / Diego Alberto Román Landeros / Efraín Vaquera González'),
(7, 'CONACYT 195766', '\"Diseño e implementación de sistema continuo de concentración de leche fresca y recuperación de agua, reduciendo costos de logística y operación para mejorar la competitividad mediante el transporte inteligente, promoviendo la gestión ambiental adecuada.  - Empresa Transportadora de Alimentos S.A de C.V. Grupo Lala – CONACYT 195766\"', '\"Diseñar e implementar un sistema continuo de concentración de leche y de recuperación de agua, así como la sistematización de procesos de producción que permitirá lograr la continuidad del proceso de concentración de leche y de la recuperación de agua.', 'M.C. Luis Amado González Vargas / M.A. Karla Verónica Rodríguez Lozano / M.A. Nancy Gabriela Marín Castañeda / M.C. Víctor Edi Manqueros Avilés'),
(8, 'ITSLerdo #001-AMBI-2016', 'Eficiencia de reacción de Peróxido de Hidrógeno en Planta Piloto usando carbón activado. ITSLerdo #001-AMBI-2016', 'Medir la eficiencia de eliminación del Peróxido de Hidrógeno usando carbón activado en diferentes proporciones como medio de empaque en los reactores de la planta piloto.', 'Juan Manuel Martínez Burrola / Armando José Cordero Escamilla / Víctor Edi Manqueros Avilés'),
(9, 'CONACYT 213121', 'Análisis Dimensional y Optimización de Línea de Molienda-Clasificación de Carbonato de Calcio Técnico', 'Empresa S.A. Reverté Carbonatos de Calcio – CONACYT 213121	\"Automatizar un prototipo de clasificador para medir las variables de presión negativa y revoluciones por minuto de la flecha del tamizador para en base a la información, parametrizar el modelo. Realizar la instrumentación y control del modelo de clasificador, así como el procesamiento de datos para la estadística básica y curvas de comportamiento. Realizar la instrumentación y el control del modelo de clasificador, a través de un tablero que permita: arranque y paro del sistema, arranque y paro del motor eléctrico, variación de la velocidad de giro del motor; medición de: velocidad angular de la flecha, presión de aspiración. También se mostrará el valor de voltaje y corriente, según el variador de velocidad. \"', 'Luis Amado González Vargas / Armando José Cordero Escamilla / María Guadalupe Flores Luevanos / Juan Martín Arzola Monreal / Víctor Edi Manqueros Avilés / Elda Moreno Nuñez'),
(10, 'ITSLerdo #002-AMBI-2016', 'Obtención de Vermicomposta a partir de Residuos Orgánicos. ITSLerdo #002-AMBI-2016	', '\"Impulsar la investigación dentro del campo de remediación de suelos, que el instituto comience con actividades sustentables en cuanto al manejo de los residuos generados en la propia institución y utilizar el producto generado para aumentar la fertilidad y la calidad del suelo en los jardines del ITSL.\"	', 'Mónica Hernández López / Silvia Adriana Vidaña Martínez'),
(11, 'ITSLerdo #001-ELEC-2016', 'Plataforma para el desarrollo de prácticas de Control de Procesos utilizando Instrumentación Virtual Remota. ITSLerdo  #001-ELEC-2016', '\"Desarrollar una plataforma que permita la interacción remota con sistemas físicos, con el objetivo de que los estudiantes puedan monitorear procesos a través de una red local de computadoras o internet, y realizar prácticas remotas en las áreas del conocimiento de electrónica, instrumentación y control de procesos.\"', 'Hesner Coto Fuentes'),
(12, 'ITSLerdo #001-INDU-2016	', 'Aplicación de herramienta Scheduling a procesos industriales de la región Laguna. ITSLerdo #001-INDU-2016	', '\"El objetivo general es realizar contribuciones científicas a la carrera de ingeniería industrial, mediante aportes significativos y originales que permitan administrar y mejorar el tiempo en diferentes aplicaciones de casos prácticos en la industria en la región laguna utilizando la herramienta Scheduling. Este trabajo de investigación en el área de la ingeniería industrial, a partir de la administración de procesos será una alternativa que contribuirá a mejorar los procesos analizados y estudiados.\"	', 'José de Jesús Linares / Santiago Tello Mijares / Luis Amado González Vargas'),
(13, 'ITSLerdo #002-POSG-2016', 'Contribuciones a un sistema semiautomático de captura y análisis de imágenes de neoplasia intraepitelial cervical (nic). ITSLerdo #002-POSG-2016', 'El objetivo es obtener el Doctorado en Ingeniería Informática y de Telecomunicación por la Universidad Autónoma de Madrid. Su estatus es tres artículos de revista JSCR y la tesis en revisión.', 'Santiago Tello Mijares'),
(14, 'ITSLerdo #004-POSG-2016', 'Diseño e implementación de prototipo de seguidor solar de dos ejes para la captación de energía solar  por medio de celdas fotovoltaica – ITSLerdo #004-POSG-2016', 'Diseñar  e implementar un prototipo de seguidor solar que contenga 2 ejes por medio del cual se optimice la captación solar y se genere electricidad.', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés / Arturo Serrano Hernández'),
(15, 'ITSLerdo #005-POSG-2016', 'Reingeniería para la adaptación de una bicicleta estática para generación de energía eléctrica y almacenamiento en una batería. fotovoltaica – ITSLerdo #005-POSG-2016', 'Adaptar un sistema que genere energía eléctrica a través de una bicicleta, basados en  conocimientos físicos, matemáticos, mecánicos y eléctricos.\"', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés / Armando Cordero Escamilla / Luis Amado González Vargas'),
(16, 'ITSLerdo #006-POSG-2016	', 'Desarrollo de prototipo de gabinete de control de movimiento usando servo sistemas Ultra 3000 de Allen Bradley – ITSLerdo #006-POSG-2016', '\"Desarrollar un prototipo de control de movimiento empleando servo sistemas industriales para desarrollar actividades de investigación y desarrollo tecnológico, docencia e impartición de cursos especializados.\"', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés'),
(17, 'ITSLerdo #007-POSG-2016', 'Desarrollo de prototipo de estación anemométrica usando el datalogger  CR850. Bradley – ITSLerdo #007-POSG-2016', '\"Desarrollar un prototipo de estación anemométrica empleando tecnología industrial  para desarrollar actividades de investigación y desarrollo tecnológico en área de monitoreo de variables ambientales, docencia e impartición de cursos especializados.\"', 'Noé Alvarado Tovar / Francisco Huerta Valenzuela'),
(18, 'ITSLerdo #008-POSG-2016', 'Desarrollo de prototipo de sistema de software y hardware  para el control de entrada y salida de equipo del área de manufactura – ITSLerdo #008-POSG-2016', 'Desarrollar un prototipo de sistema informático que permita el control de la entrada y salida de equipo del área de manufactura.', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés / Francisco Huerta Valenzuela'),
(19, 'ITSLerdo #009-POSG-2016', 'Desarrollo de prototipos de robots manipuladores de 6 grados de libertad con servo motores DS3115mg y MG996R – ITSLerdo #009-POSG-2016', '\"Desarrollar prototipos con robots manipuladores pequeño de 6 grados de libertad para desarrollar actividades de investigación y desarrollo tecnológico, docencia e impartición de cursos especializados.\"', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés / Francisco Huerta Valenzuela'),
(20, 'ITSLerdo #010-POSG-2016	', 'Aplicación inteligente para una maquina despachadora de alimentos saludables – ITSLerdo #010-POSG-2016', '\"Desarrollar un Software Inteligente para una maquina despachadora  que sea capaz de generar un menú  saludable de acuerdo al peso, estatura  y edad de la persona\"', 'Karla Verónica Rodríguez Lozano'),
(21, 'ITSLerdo #003-POSG-2016', 'Desarrollo de página Web para el área de posgrado – ITSLerdo #003-POSG-2016', 'Desarrollar una Página Web para el área de posgrado que cuente con la información de interés para los alumnos que se encuentran estudiando en esta área y para los aspirantes a ingresar a la especialización en Ingeniería Mecatrónica como a la Maestría en ingeniería Mecatrónica del ITSL cumpliendo con los requerimientos mínimos del TecNM y del CONACyT', 'Ríos Marmolejo César'),
(22, 'ITSLerdo #001-SIST-2016', 'Mantenimiento al Sistema de Actividades Complementarias (SAC - creación de la segunda versión-Alumnos)  ITSLerdo #001-SIST-2016', '\"Coadyuvar en la formación integral de los estudiantes del Instituto Tecnológico Superior de Lerdo, brindando un conjunto de herramientas que faciliten el control de la acreditación de las actividades complementarias.\"', 'María Guadalupe Flores Luevanos / Elda Moreno Núñez'),
(23, 'ITSLerdo #002-SIST-2016', 'Desarrollo de una aplicación móvil para la geolocalización de un edificio en el ITSL utilizando tecnología IPS – ITSLerdo #002-SIST-2016', 'Desarrollar una aplicación móvil para la geolocalización interna de un edificio en el Instituto Tecnológico Superior de Lerdo utilizando IPS.', 'María Guadalupe Flores Luévanos / Elda Moreno Núñez / Karla Verónica Rodríguez Lozano'),
(24, 'ITSLerdo #003-SIST-2016	', 'Configuración e Instalación de una Infraestructura de red  para la Geolocalización de un Edifico en el Instituto Tecnológico Superior de Lerdo Utilizando Tecnología IPS – ITSLerdo #003-SIST-2016', 'Configurar e instalar una infraestructura de red en el ITSL para la geolocalización interna de un edificio “Utilizando tecnología IPS”', 'Karla Verónica Rodríguez Lozano / José Ángel Candela Saucedo / Juan Martín Arzola Monreal.'),
(25, 'ITSLerdo #001-AMBI-2017', 'Aprovechamiento de residuos orgánicos provenientes del ITSL para la generación de vermicomposta. ITSLerdo #001-AMBI-2017', 'Aprovechamiento de residuos orgánicos provenientes del ITSL para la generación de vermicomposta.', 'Silvia Adriana Vidaña Martínez / Mónica Hernández López / Adriana Viramontes Acosta / Tania Elizabeth Velásquez Chávez'),
(26, 'ITSLerdo #002-AMBI-2017', 'Cuantificación de Metano como indicador de Biorremediación de hidrocarburos mediante lodos  granulares. ITSLerdo #002-AMBI-2017', 'Cuantificar la producción de gas metano como principal subproducto en la degradación de hidrocarburos haciendo uso de lodos granulares implementando reactores anaerobios.', 'ITSLerdo: Juan Manuel Martínez Burrola / Luis Alejandro Contreras pinto            Universidad IberoAmericana: José Antonio Martínez Villalba'),
(27, 'ITSLerdo #003-AMBI-2017	', 'Validación de proceso en planta piloto para tratamiento de agua sanitizante. ITSLerdo #003-AMBI-2017', 'Validar el proceso para tratamiento de agua sanitizante en una planta piloto semiautomatizada respecto a la norma 127-SSA1.', 'Juan Manuel Martínez Burrola / Armando José Cordero Escamilla / Víctor Edi Manqueros Avilés'),
(28, 'ITSLerdo #004-AMBI-2017', 'Clasificación y aprovechamiento de residuos en el ITSL. ITSLerdo #004-AMBI-2017', '\"Implementar en el ITSL un programa de reciclaje de PET, aluminio y papel (hojas, libros, revistas, etc.). Se llevara a cabo mediante un prototipo de contenedor para cada uno de ellos, así como pláticas para concientizar a todo el alumnado de esta institución.\"', 'Tania Elizabeth Velásquez Chávez / Silvia Adriana Vidaña Martínez / Mónica Hernández López / Adriana Viramontes Acosta'),
(29, 'ITSLerdo #005-AMBI-2017	', 'Caracterización del agua  y análisis estadístico del consumo en el Instituto Tecnológico Superior de Lerdo. ITSLerdo #005-AMBI-2017', '\"Analizar la calidad y administración del agua que se proporciona en el Instituto Tecnológico Superior de Lerdo, para la viabilidad de una planta purificadora.\"', 'Adriana Viramontes Acosta / Tania Elizabeth Velásquez Chávez / Silvia Adriana Vidaña Martínez'),
(30, 'ITSLerdo #002-POSG-2017	', 'Sistema microscópico semiautomático de adquisición y análisis de imágenes de las células cervicales en citología liquida mediante fluidica por micro-canales', 'Implementación de la interfaz y control del servomotor.	', 'Santiago Tello Mijares'),
(31, 'ITSLerdo #001-POSG-2017', 'Diseño y construcción de un MiniCNC ITSLerdo #001-POSG-2017', 'Diseño y construcción de un miniCNC para el desarrollo de grabado en diferentes materiales así como el desarrollo de circuitos impresos.', 'César Ríos Marmolejo'),
(32, 'ITSLerdo #003-POSG-2017', 'Diseño y construcción de una dobladora de lámina ITSLerdo #003-POSG-2017', 'Diseño y construcción de una dobladora de lámina para el desarrollo de cajas para proyectos de los alumnos.', 'César Ríos Marmolejo'),
(33, 'ITSLerdo #004-POSG-2017', 'Análisis De Armónicos Mediante El Procesamiento Digital de Señales en Sistemas de Potencia ITSLerdo #004-POSG-2017', 'Implementar  diseño para analizar la calidad de señal de alimentación de energía de potencia por medio de un sistema electrónico-eléctrico-sistematizado de entrada al instituto tecnológico superior de lerdo.', 'Luís Amado González Vargas / Roberto Cuellar Alcala'),
(34, 'ITSLerdo #001-SIST-2017', 'Actualización al Sistema de Actividades Complementarias conforme al manual de lineamientos del Tecnológico Nacional de México (creación del SAC 3.0). ITSLerdo #001-SIST-2017', '\"Actualizar el Sistema de Actividades Complementarias (SAC) del ITSL, para su integración de conformidad a lo dispuesto en el manual de lineamientos del Tecnológico Nacional de México.\"', 'María Guadalupe Flores Luevanos / Elda Moreno Núñez'),
(35, 'ITSLerdo #002-SIST-2017', 'Análisis de una Infraestructura de red  para la Geolocalización dentro del Instituto Tecnológico Superior de Lerdo Utilizando Tecnología IPS. ITSLerdo #002-SIST-2017', 'Analizar una infraestructura de red para la geolocalización dentro del ITSL “Utilizando tecnología IPS”.	', 'Karla Verónica Rodríguez Lozano / José Ángel Candela Saucedo'),
(36, 'ITSLerdo #003-SIST-2017', 'CONINCI App. ITSLerdo #003-SIST-2017', 'Desarrollar una aplicación para dispositivos móviles Android que le permita al alumno seleccionar las actividades del CONINCI y recibir notificaciones de estas.', 'Karla Verónica Rodríguez Lozano / María Guadalupe Flores Luevanos / Elda Moreno Núñez'),
(37, 'ITSLerdo #005-POSG-2017', '\"DISEÑO E IMPLEMENTACIÓN DE UN MODULO DIDÁCTICO PARA EL ANÁLISIS DE RESPUESTAS DE CONTROLADORES P, PI Y PID PARA EL LABORATORIO DE ELECTRÓNICA DEL TECNOLÓGICO DE LERDO. ITSLerdo #005-POSG-2017\"', '\"Diseño de un Kit didáctico que, mediante el control de una planta (la cual puede ser intercambiable, según la variable que se desee, velocidad y posición de motor, ángulo en péndulo, temperatura) ayude a comprender mejor el funcionamiento de los diferentes tipos de controladores que existen y poder hacer la comparación de control analógico vs control digital.\"', 'Luís Amado González Vargas / Pascual Salazar Castillo'),
(38, 'CONACYT 231156', 'Ecosistema de aprendizaje para mejorar el pensamiento matemático en preescolar con realidad aumentada.- Empresa Fundación interdisciplinaria para el desarrollo empresarial S de R.L. de C.V. - CONACYT 231156', '\"Mejorar el proceso y formación de habilidades matemáticas con herramientas de tecnologías de información, como es la realidad aumentada acompañada de cuadernos de trabajo con patrones, mismos que podrán ser visualizados con los desarrollos que componen este ecosistema educativo, los cuales facilitarán la organización, administración y formación tanto del alumno de preescolar como para las educadoras.\"', 'Karla Verónica Rodríguez Lozano / María Guadalupe Flores Luévanos / Elda Moreno Núñez'),
(39, 'CONACYT 242497	', '\"Diseño e implementación de un nuevo sistema continuo de concentración de leche para reducir costos de logística y operación, y eliminar al 90% la extracción de agua para la planta. CONACYT 242497\"', '\"a) implementar el nuevo clúster hidro-neumático de válvulas a prueba de contaminación cruzada, b) implementar las líneas para realizar ciclos de limpieza y producción en forma simultánea, c) ampliar la capacidad instalada de suministros generales (refrigeración, electricidad, vapor etc.), d) añadir las unidades adicionales de concentración, y e) realizar las pruebas piloto de funcionamiento.\"', 'Noé Alvarado Tovar / Víctor Edi Manqueros Avilés / Armando Cordero Escamilla / Luis Amado González Vargas / Francisco Huerta Valenzuela / Arturo Serrano Hernández  / Diego Alberto Román Landeros / Efraín Vaquera González');

